examples.config:
Profile {
  Name = operator
  Description = "Run and watch backups"
}

Profile {
  Name = operator
  Job ACL = backup-web, restore-files
}

Profile {
  Name = operator
  Client ACL = web-fd, db-fd
}

Profile {
  Name = operator
  Storage ACL = File
}

Profile {
  Name = operator
  Schedule ACL = WeeklyCycle
}

Profile {
  Name = operator
  Pool ACL = Full, Incremental
}

Profile {
  Name = operator
  Command ACL = status, list, llist, restore, .api, .help
}

Profile {
  Name = operator
  File Set ACL = LinuxAll
}

Profile {
  Name = operator
  Catalog ACL = MyCatalog
}

Profile {
  Name = operator
  Plugin Options ACL = python:module_name=bareos-fd-local-fileset
}
